#pragma once
// Explicit, read-only shell diagnostics. No window titles or user content.
namespace glass {
inline std::wstring diagnosticProcess(DWORD pid){wchar_t p[32768]{};DWORD n=32768;HANDLE process=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pid);if(process){QueryFullProcessImageNameW(process,0,p,&n);CloseHandle(process);}std::wstring name=p;auto at=name.find_last_of(L'\\');return name.substr(at==name.npos?0:at+1);}
inline bool diagnosticHost(const std::wstring&name){return !_wcsicmp(name.c_str(),L"TextInputHost.exe")||!_wcsicmp(name.c_str(),L"explorer.exe")||!_wcsicmp(name.c_str(),L"ShellHost.exe")||!_wcsicmp(name.c_str(),L"ShellExperienceHost.exe")||!_wcsicmp(name.c_str(),L"StartMenuExperienceHost.exe");}
inline void diagnosticWindow(HWND h,std::wstring&output){DWORD pid=0;DWORD tid=GetWindowThreadProcessId(h,&pid);wchar_t cls[256]{};GetClassNameW(h,cls,256);RECT r{};GetWindowRect(h,&r);DWORD cloaked=0;DwmGetWindowAttribute(h,DWMWA_CLOAKED,&cloaked,sizeof(cloaked));output+=L"pid="+std::to_wstring(pid)+L" tid="+std::to_wstring(tid)+L" exe="+diagnosticProcess(pid)+L" class="+cls+L" visible="+std::to_wstring(IsWindowVisible(h)!=FALSE)+L" cloaked="+std::to_wstring(cloaked)+L" bounds="+std::to_wstring(r.left)+L","+std::to_wstring(r.top)+L","+std::to_wstring(r.right)+L","+std::to_wstring(r.bottom)+L"\r\n";}
inline int diagnoseShell(const std::wstring&path){std::wstring output=L"Read-only shell windows (screen pixels; no titles).\r\n";EnumWindows([](HWND h,LPARAM data)->BOOL{DWORD pid=0;GetWindowThreadProcessId(h,&pid);if(!diagnosticHost(diagnosticProcess(pid)))return TRUE;auto&out=*reinterpret_cast<std::wstring*>(data);diagnosticWindow(h,out);EnumChildWindows(h,[](HWND child,LPARAM p)->BOOL{diagnosticWindow(child,*reinterpret_cast<std::wstring*>(p));return TRUE;},data);return TRUE;},reinterpret_cast<LPARAM>(&output));int n=WideCharToMultiByte(CP_UTF8,0,output.data(),(int)output.size(),nullptr,0,nullptr,nullptr);std::string utf8(n,0);WideCharToMultiByte(CP_UTF8,0,output.data(),(int)output.size(),utf8.data(),n,nullptr,nullptr);HANDLE file=CreateFileW(path.c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return 1;DWORD written=0;BOOL ok=WriteFile(file,utf8.data(),n,&written,nullptr);CloseHandle(file);return ok&&written==(DWORD)n?0:1;}
}
